using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new System.Exception("Unsaved scene");BuildEnrothLinkedOpenWorld.Build();result.Log("Linked world rebuilt from current standalone regions");}}